    <script>function openHistoryModal(id){document.getElementById(id).classList.remove('hidden');document.getElementById(id).classList.add('flex')}function closeHistoryModal(id){document.getElementById(id).classList.add('hidden');document.getElementById(id).classList.remove('flex')}@can('login_history.delete')document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-login-id]').forEach(row=>{let timer;row.addEventListener('pointerdown',event=>{if(event.target.matches('input,button'))return;timer=setTimeout(()=>{const modal=row.closest('.fixed');modal.querySelector('[data-login-selection]').classList.remove('hidden');modal.querySelector('[data-login-selection]').classList.add('flex');modal.querySelectorAll('.login-select').forEach(box=>box.classList.remove('hidden'));row.querySelector('.login-select').checked=true},650)});['pointerup','pointerleave','pointercancel'].forEach(name=>row.addEventListener(name,()=>clearTimeout(timer)))});document.querySelectorAll('[data-login-select-all]').forEach(box=>box.addEventListener('change',event=>event.target.closest('.fixed').querySelectorAll('.login-select').forEach(item=>item.checked=event.target.checked)));document.querySelectorAll('[data-cancel-logins]').forEach(button=>button.addEventListener('click',()=>{const modal=button.closest('.fixed');modal.querySelector('[data-login-selection]').classList.add('hidden');modal.querySelector('[data-login-selection]').classList.remove('flex');modal.querySelectorAll('.login-select').forEach(box=>{box.checked=false;box.classList.add('hidden')})}));document.querySelectorAll('[data-delete-logins]').forEach(button=>button.addEventListener('click',async()=>{const modal=button.closest('.fixed'),ids=[...modal.querySelectorAll('.login-select:checked')].map(box=>box.closest('[data-login-id]').dataset.loginId);if(!ids.length)return;const password=prompt('{{ __('Enter your password to confirm deletion.') }}');if(password===null)return;const response=await fetch('{{ route('admin.history.logins.destroy') }}',{method:'DELETE',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({ids,password})});if(!response.ok){alert('{{ __('Incorrect password.') }}');return}ids.forEach(id=>modal.querySelector(`[data-login-id="${id}"]`)?.remove());modal.querySelector('[data-cancel-logins]').click()}))});@endcan</script>
