    @can('login_history.delete')<script>document.addEventListener('DOMContentLoaded',()=>document.querySelectorAll('[data-delete-logins]').forEach(button=>button.addEventListener('click',async event=>{event.stopImmediatePropagation();const modal=button.closest('.fixed'),ids=[...modal.querySelectorAll('.login-select:checked')].map(box=>box.closest('[data-login-id]').dataset.loginId);if(!ids.length||!confirm('{{ __('Move the selected history entries to the trash?') }}'))return;const response=await fetch('{{ route('admin.history.logins.destroy') }}',{method:'DELETE',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Content-Type':'application/json',Accept:'application/json'},body:JSON.stringify({ids})});if(!response.ok){alert('{{ __('Action not allowed.') }}');return}ids.forEach(id=>modal.querySelector(`[data-login-id="${id}"]`)?.remove());modal.querySelector('[data-cancel-logins]').click()},true)));</script>@endcan
